class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        auto gcd = [](int a, int b) {
            while (b) { int t = a % b; a = b; b = t; }
            return a;
        };
        bool cop[51][51];
        for (int a = 1; a <= 50; a++)
            for (int b = 1; b <= 50; b++)
                cop[a][b] = (gcd(a, b) == 1);

        vector<int> ans(n, -1);
        // stacks[v] holds (depth, node) for ancestors with value v on current path
        vector<vector<pair<int,int>>> stacks(51);
        // explicit DFS: {node, parent, depth, exitFlag}
        vector<array<int,4>> stk;
        stk.push_back({0, -1, 0, 0});
        while (!stk.empty()) {
            auto fr = stk.back(); stk.pop_back();
            int u = fr[0], p = fr[1], d = fr[2], exitFlag = fr[3];
            if (exitFlag) {
                stacks[nums[u]].pop_back();
                continue;
            }
            int best = -1, bestDepth = -1;
            for (int v = 1; v <= 50; v++) {
                if (!cop[nums[u]][v] || stacks[v].empty()) continue;
                auto& top = stacks[v].back();
                if (top.first > bestDepth) {
                    bestDepth = top.first;
                    best = top.second;
                }
            }
            ans[u] = best;
            stacks[nums[u]].push_back({d, u});
            stk.push_back({u, p, d, 1});
            for (int w : adj[u])
                if (w != p)
                    stk.push_back({w, u, d + 1, 0});
        }
        return ans;
    }
};
